INSERT INTO `use_cases` VALUES ('178883958415333kw','AI Chatbot / Copilot Layer — TRT Compound Front Door','IT / Digital Transformation','{\"id\": \"178883958415333kw\", \"kpi\": \"จำนวนผู้ใช้งาน Chatbot ต่อวัน, เวลาตอบสนองเฉลี่ย < 5 วินาที, User Satisfaction Score > 4/5\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"ลดเวลาค้นหาข้อมูลของพนักงาน 30%, เพิ่มความเร็วในการตัดสินใจ\", \"data\": 2, \"dept\": \"IT / Digital Transformation\", \"name\": \"AI Chatbot / Copilot Layer — TRT Compound Front Door\", \"risk\": 4, \"owner\": \"\", \"risks\": \"ข้อมูลจากหลายระบบมี format ต่างกัน ต้องทำ data integration ก่อน, ความปลอดภัยของข้อมูล\", \"score\": 74, \"users\": \"\", \"aiType\": \"text\", \"impact\": 4, \"output\": \"Chatbot interface ที่ผู้ใช้ถามข้อมูล สั่งงาน และรับสรุปรายงานได้ทันที, AI Front Door ที่ orchestrate AI Agents อื่นๆ\", \"control\": \"\", \"latency\": \"realtime\", \"problem\": \"ระบบปัจจุบันเป็น Data Silo แยกส่วนระหว่าง Sales, Planning, Production, Engineering, Quality ทำให้ผู้ใช้งานต้องเข้าหลายระบบเพื่อหาข้อมูล เสียเวลาและข้อมูลไม่ต่อเนื่อง\", \"refStep\": \"\", \"approver\": \"\", \"hardware\": \"\", \"language\": \"th\", \"priority\": \"med\", \"solution\": \"สร้าง Chatbot / Copilot Layer เป็น AI Front Door รวมข้อมูลจาก ERP, Sheets, SCADA, NC, PM/BM, Formula, Test Results ไว้ที่จุดเดียว ผู้ใช้สามารถถามคำถาม สั่งงาน และรับสรุปผ่าน chat interface\", \"attachRef\": \"TRT_Compound_AI_Transformation_2026_2028_v3_chatbot_layer.pptx — Slide 4 (Vision)\", \"resources\": \"Data Engineer, AI/ML Engineer, UX Designer, ทีม IT\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 2, \"availability\": \"business\", \"redesignDesc\": \"Chatbot interface ที่ผู้ใช้ถามข้อมูล สั่งงาน และรับสรุปรายงานได้ทันที, AI Front Door ที่ orchestrate AI Agents อื่นๆ\", \"recommendation\": \"เริ่ม Phase 1: เชื่อมต่อ ERP และ NC ก่อน แล้วขยายไปยังระบบอื่น, ใช้ LLM แบบ RAG กับข้อมูลภายใน\", \"dataSensitivity\": \"internal\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('1788839584153cacs','GM Compound Copilot — AI Executive Brief และ Daily Dashboard','Management','{\"id\": \"1788839584153cacs\", \"kpi\": \"เวลาที่ผู้บริหารใช้ในการเตรียม Daily Report ลดลง, การตัดสินใจเร็วขึ้น, User Adoption Rate\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"เพิ่มความเร็วในการตัดสินใจ ลด Risk ที่พลาดไป ลดเวลาประชุม Morning Brief\", \"data\": 2, \"dept\": \"Management\", \"name\": \"GM Compound Copilot — AI Executive Brief และ Daily Dashboard\", \"risk\": 4, \"owner\": \"\", \"risks\": \"การเชื่อมต่อ Real-time กับทุกระบบ, ความแม่นยำของ AI Summary ที่ต้องไม่ทำให้เข้าใจผิด\", \"score\": 82, \"users\": \"\", \"aiType\": \"text\", \"impact\": 4, \"output\": \"Executive Dashboard Real-time, AI Daily Briefing Summary, Chatbot Interface สำหรับ GM ถามข้อมูลและสั่งงาน AI Agents\", \"control\": \"\", \"latency\": \"nearrealtime\", \"problem\": \"ผู้บริหารต้องใช้เวลานานในการรวบรวมข้อมูลจากหลายแผนก เพื่อเข้าใจสถานการณ์ภาพรวมของโรงงาน ทำให้การตัดสินใจล่าช้า และอาจพลาดสัญญาณเตือน\", \"refStep\": \"\", \"approver\": \"\", \"hardware\": \"\", \"language\": \"th\", \"priority\": \"high\", \"solution\": \"GM Copilot รวม Executive Dashboard แสดง Production Achievement, Delivery Risk, Machine Health, Open NC, Inventory Risk พร้อม AI Daily Summary Briefing และ Chatbot Interface ให้ GM ถามและสั่งงานได้โดยตรง\", \"attachRef\": \"TRT_Compound_AI_Transformation_2026_2028_v3_chatbot_layer.pptx — Slide 10 (GM Copilot)\", \"resources\": \"Data Engineer, AI Engineer, BI Developer, ข้อมูลจากทุกแผนก\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 2, \"availability\": \"business\", \"redesignDesc\": \"Executive Dashboard Real-time, AI Daily Briefing Summary, Chatbot Interface สำหรับ GM ถามข้อมูลและสั่งงาน AI Agents\", \"recommendation\": \"เริ่มจาก Static Dashboard ก่อน แล้วค่อยเพิ่ม AI Summary และ Chatbot Interface ใน Phase ถัดไป\", \"dataSensitivity\": \"confidential\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('1788839584153k9o1','Production Optimization Agent — ควบคุม Banbury/Kneader ด้วย AI','Production','{\"id\": \"1788839584153k9o1\", \"kpi\": \"ลด Reject Rate X%, เพิ่ม Process Capability (Cpk), ลด Rework\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"ลด Reject Rate ลด Rework ต้นทุน เพิ่ม Throughput\", \"data\": 3, \"dept\": \"Production\", \"name\": \"Production Optimization Agent — ควบคุม Banbury/Kneader ด้วย AI\", \"risk\": 3, \"owner\": \"\", \"risks\": \"ความเสถียรของ SCADA Data Connection, Latency ของ Real-time Processing, การยอมรับของ Operator\", \"users\": \"\", \"aiType\": \"numeric\", \"impact\": 4, \"latency\": \"\", \"refStep\": \"\", \"approver\": \"\", \"hardware\": \"Edge Computing / Industrial IoT Gateway\", \"language\": \"\", \"solution\": \"AI Agent วิเคราะห์ Torque Curve, Rotor Speed, Specific Energy, Ram Pressure, Drop Temperature แบบ Real-time เพื่อแนะนำค่า Parameter ที่เหมาะสม พยากรณ์คุณภาพ และแจ้งเตือนล่วงหน้าเมื่อกระบวนการผิดปกติ\", \"attachRef\": \"TRT_Compound_AI_Transformation_2026_2028_v3_chatbot_layer.pptx — Slide 7 (Production Optimization Agent)\", \"resources\": \"Process Engineer, Data Engineer, IoT Specialist, SCADA Data\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 3, \"availability\": \"\", \"redesignDesc\": \"Optimal Parameter Recommendation แบบ Real-time, Quality Prediction Score, Early Warning Alert Dashboard\", \"dataAvailable\": \"\", \"recommendation\": \"ติดตั้ง Sensor เพิ่มถ้าจำเป็น, ใช้ Time-Series ML Model, เริ่ม Pilot กับ 1 เครื่องก่อน\", \"dataSensitivity\": \"\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('1788839584153ll4i','Predictive Maintenance Agent — ทำนาย Breakdown จากแผน PM','Engineering / Maintenance','{\"id\": \"1788839584153ll4i\", \"kpi\": \"ลด Breakdown 40%, ลดต้นทุน Emergency Repair, Spare Parts Forecast Accuracy > 85%\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"ลด Breakdown 40% ลดค่าซ่อมฉุกเฉิน เพิ่ม Machine Availability\", \"data\": 2, \"dept\": \"Engineering / Maintenance\", \"name\": \"Predictive Maintenance Agent — ทำนาย Breakdown จากแผน PM\", \"risk\": 3, \"owner\": \"\", \"risks\": \"ข้อมูล Breakdown History ต้องครบและมีรายละเอียดเพียงพอ, Sensor Data อาจต้องติดตั้งเพิ่ม\", \"users\": \"\", \"aiType\": \"numeric\", \"impact\": 4, \"latency\": \"\", \"refStep\": \"\", \"approver\": \"\", \"hardware\": \"Vibration Sensor / Temperature Sensor (ถ้ายังไม่มี)\", \"language\": \"\", \"solution\": \"AI Agent วิเคราะห์ PM Records, BM Records, Breakdown History, Spare Parts Data เพื่อทำนายโอกาส Breakdown ล่วงหน้า แนะนำงาน Maintenance ที่ควรทำ และพยากรณ์ความต้องการ Spare Parts\", \"attachRef\": \"TRT_Compound_AI_Transformation_2026_2028_v3_chatbot_layer.pptx — Slide 9 (Predictive Maintenance Agent)\", \"resources\": \"Maintenance Engineer, Data Scientist, IoT/Sensor Data\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 3, \"availability\": \"\", \"redesignDesc\": \"Failure Prediction Score พร้อม Timeline, Maintenance Recommendation List, Spare Parts Forecast Report\", \"dataAvailable\": \"\", \"recommendation\": \"เริ่มจาก Critical Machine ที่ Breakdown บ่อยที่สุด, ใช้ Survival Analysis + Time-Series Forecasting\", \"dataSensitivity\": \"\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('1788839584153m9yp','Compound Formulation Agent — AI แนะนำสูตร ลด Trial Batch','R&D','{\"id\": \"1788839584153m9yp\", \"kpi\": \"ลดจำนวน Trial Batch 30-50%, ลดเวลาพัฒนาสูตรใหม่, Property Prediction Accuracy > 85%\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"ลดต้นทุน Trial Batch 30-50%, เพิ่มความเร็วในการพัฒนาสูตรใหม่\", \"data\": 2, \"dept\": \"R&D\", \"name\": \"Compound Formulation Agent — AI แนะนำสูตร ลด Trial Batch\", \"risk\": 3, \"owner\": \"\", \"risks\": \"คุณภาพและความครบถ้วนของ Historical Formula Data, ความแม่นยำของ Property Prediction Model\", \"users\": \"\", \"aiType\": \"agent\", \"impact\": 4, \"latency\": \"\", \"refStep\": \"\", \"approver\": \"\", \"hardware\": \"\", \"language\": \"\", \"solution\": \"AI Agent วิเคราะห์ Historical Formula, Rheometer Data, Physical Test Results และ Cost Data เพื่อแนะนำสูตร Compound ที่เหมาะสม วางแผน DOE (Design of Experiment) และทำนายคุณสมบัติของสูตรก่อนทดลองจริง\", \"attachRef\": \"TRT_Compound_AI_Transformation_2026_2028_v3_chatbot_layer.pptx — Slide 6 (Formulation Agent)\", \"resources\": \"Data Scientist, R&D Team, ข้อมูลสูตร+ผลทดสอบย้อนหลัง\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 3, \"availability\": \"\", \"redesignDesc\": \"Formula Recommendation พร้อมเหตุผล, DOE Plan, Property Prediction Report\", \"dataAvailable\": \"\", \"recommendation\": \"ใช้ ML Model (Gradient Boosting / Neural Network) + DOE Optimization, เริ่มจาก Compound Series ที่มีข้อมูลมากที่สุด\", \"dataSensitivity\": \"\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('1788839584153rqmn','NC & Quality Agent — AI วิเคราะห์ Root Cause และ CAPA อัตโนมัติ','Quality','{\"id\": \"1788839584153rqmn\", \"kpi\": \"ลดเวลา Root Cause Analysis 70%, ลด Repeat NC, CAPA Effectiveness Rate\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"ลดเวลา QA 70%, ลด Customer Complaint, ป้องกัน NC ซ้ำ\", \"data\": 4, \"dept\": \"Quality\", \"name\": \"NC & Quality Agent — AI วิเคราะห์ Root Cause และ CAPA อัตโนมัติ\", \"risk\": 3, \"owner\": \"\", \"risks\": \"ความครบถ้วนของ Historical NC Data, การ Standardize Root Cause Categories\", \"score\": 80, \"users\": \"\", \"aiType\": \"text\", \"impact\": 4, \"output\": \"Root Cause Recommendation Report, Similar Case List, CAPA Suggestion พร้อมความเชื่อมั่น\", \"control\": \"\", \"latency\": \"nearrealtime\", \"problem\": \"การวิเคราะห์ Root Cause ของ NC (Non-Conformance) และ Customer Complaint ใช้เวลานาน ต้องอาศัยผู้เชี่ยวชาญ และบ่อยครั้ง Root Cause เดิมซ้ำซากเพราะไม่ได้เรียนรู้จาก Case ที่ผ่านมา\", \"refStep\": \"\", \"approver\": \"\", \"hardware\": \"\", \"language\": \"th\", \"priority\": \"high\", \"solution\": \"AI Agent วิเคราะห์ NC Records, Customer Complaints, CAPA History ด้วย Why-Why Analysis อัตโนมัติ ค้นหา Similar Case จากอดีต และแนะนำ CAPA ที่เคยได้ผล\", \"attachRef\": \"TRT_Compound_AI_Transformation_2026_2028_v3_chatbot_layer.pptx — Slide 8 (NC & Quality Agent)\", \"resources\": \"Quality Engineer, Data Analyst, Historical NC/CAPA Database\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 4, \"availability\": \"business\", \"redesignDesc\": \"Root Cause Recommendation Report, Similar Case List, CAPA Suggestion พร้อมความเชื่อมั่น\", \"dataAvailable\": \"Index P-Car\\nWHY Why มาตรฐาน\\nTrouble Shooting\", \"recommendation\": \"ใช้ LLM + Knowledge Graph สำหรับ Similar Case Search, เชื่อมต่อกับระบบ QMS ที่มีอยู่\", \"dataSensitivity\": \"internal\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('1788839584153vuud','Sales & RFQ Agent — AI ประเมิน RFQ เร็วขึ้น ลดเวลา','Sales','{\"id\": \"1788839584153vuud\", \"kpi\": \"ลดเวลา RFQ จาก X วันเหลือ Y ชั่วโมง, ความแม่นยำ CTQ > 90%, Cost Estimate Error < 10%\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"ลดเวลา RFQ จากหลายวันเหลือไม่กี่ชั่วโมง เพิ่มจำนวน RFQ ที่รับได้\", \"data\": 2, \"dept\": \"Sales\", \"name\": \"Sales & RFQ Agent — AI ประเมิน RFQ เร็วขึ้น ลดเวลา\", \"risk\": 4, \"owner\": \"\", \"risks\": \"ความแม่นยำของการอ่าน Drawing/Spec, ข้อมูล Historical Quote ต้องครบถ้วน\", \"score\": 79, \"users\": \"\", \"aiType\": \"text\", \"impact\": 4, \"output\": \"Material Recommendation, Risk Assessment, Cost Estimate เบื้องต้น ใน RFQ แต่ละใบ\", \"control\": \"\", \"latency\": \"batch\", \"problem\": \"กระบวนการตอบ RFQ ใช้เวลานาน ต้องอาศัยผู้เชี่ยวชาญหลายคน ในการวิเคราะห์ Drawing, Specification เพื่อประเมิน CTQ, Material และต้นทุน ทำให้ตอบลูกค้าช้า เสียโอกาสทางธุรกิจ\", \"refStep\": \"\", \"approver\": \"\", \"hardware\": \"\", \"language\": \"th\", \"priority\": \"high\", \"solution\": \"AI Agent วิเคราะห์ RFQ Document (Drawing, Specification) อัตโนมัติ ระบุ CTQ (Critical to Quality) แนะนำวัสดุ Compound, ประเมินความเสี่ยง และประมาณต้นทุนเบื้องต้นได้ทันที\", \"attachRef\": \"TRT_Compound_AI_Transformation_2026_2028_v3_chatbot_layer.pptx — Slide 5 (Sales & RFQ Agent)\", \"resources\": \"AI/ML Engineer, Sales Team, Data ราคาวัตถุดิบ, ฐานข้อมูล Formula\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 2, \"availability\": \"business\", \"redesignDesc\": \"Material Recommendation, Risk Assessment, Cost Estimate เบื้องต้น ใน RFQ แต่ละใบ\", \"recommendation\": \"เริ่มจาก Compound ที่มี Historical Data มาก (A, B, C) ก่อน แล้วขยาย, ใช้ Document AI + LLM\", \"dataSensitivity\": \"confidential\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_1788838421450_6693','Smart Factory Upgrade: ระบบอัตโนมัติสายการผลิต Molding–Deflashing–Trimming–Slitting–Inspection–Packing (ชิ้นงานยาง)','Auto','{\"id\": \"uc_1788838421450_6693\", \"kpi\": \"\", \"kqi\": \"อัตราการตรวจพบของเสียถูกต้อง (accuracy) ของระบบ AI Vision Inspection ≥ 90%\", \"qwp\": \"QWP-A12 (00) — การลดต้นทุนและปรับปรุงกระบวนการ\", \"roi\": \"\", \"data\": 3, \"dept\": \"Auto\", \"name\": \"Smart Factory Upgrade: ระบบอัตโนมัติสายการผลิต Molding–Deflashing–Trimming–Slitting–Inspection–Packing (ชิ้นงานยาง)\", \"risk\": 3, \"owner\": \"PCT\", \"risks\": \"\", \"users\": \"2 คน/กะ (4 คน/วัน รวม 2 กะ)\", \"aiType\": \"agent\", \"impact\": 4, \"output\": \"สายการผลิตอัตโนมัติที่ใช้คนเหลือ 2 คน/กะ (จากเดิม 6 คน/กะ) พร้อมระบบตรวจสอบคุณภาพด้วย AI Vision\", \"control\": \"ความหนาของครีบยาง (Flash) หลังขึ้นรูปต้องไม่เกิน 0.05 มม. ก่อนเข้าสู่ขั้นตอนขัดเยือกแข็ง\", \"latency\": \"ทันที (< 1 วินาที)\", \"problem\": \"ปัจจุบันใช้แรงงานคน 12 คน/วัน (2 กะ × 6 คน) มีขั้นตอนช้า เช่น เล็มครีบด้วยกรรไกร (4.21 วิ/ชิ้น), ตรวจด้านในด้วยสายตา (3.87 วิ/ชิ้น)\", \"refStep\": \"ขั้นตอนที่ 9\", \"approver\": \"\", \"hardware\": \"\", \"language\": \"Thai\", \"solution\": \"Manual ทุกขั้นตอน: (1) พนักงานคนที่ 1 ใส่ Compound C แล้วปลดชิ้นงานด้วย Jig ได้ 240 ชิ้น/รอบ (2) พนักงานคนที่ 1 เดินเครื่อง Deflashing 2 นาที แยกชิ้นงานและครีบด้วยมือ (3) พนักงานคนที่ 2-3 ใช้กรรไกรตกแต่งละเอียด เฉลี่ย 4.21 วินาที/ชิ้น (4) พนักงานคนที่ 4 ป้อนชิ้นงานเข้า Jig ผ่าด้วยมือ เฉลี่ย 0.95 วินาที/ชิ้น (5) พนักงานคนที่ 5-6 ตรวจสอบผิวด้านในด้วยสายตา เฉลี่ย 3.87 วินาที/ชิ้น (6) พนักงานคนที่ 4 ใช้เวลาที่เหลือแพ็คชิ้นงานลงกล่องด้วยมือ\", \"attachRef\": \"\", \"resources\": \"\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 2, \"availability\": \"เกือบตลอดเวลา 24x7 (99.5%)\", \"redesignDesc\": \"สายการผลิตอัตโนมัติที่ใช้คนเหลือ 2 คน/กะ (จากเดิม 6 คน/กะ) พร้อมระบบตรวจสอบคุณภาพด้วย AI Vision\", \"recommendation\": \"\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_1788838844805_9410','AI ช่วยวิเคราะห์และ Optimize เงื่อนไขการฉีดขึ้นรูปจากผล CAE Simulation (ออกแบบแม่พิมพ์ใหม่)','TRT Mold','{\"id\": \"uc_1788838844805_9410\", \"kpi\": \"ลดระยะเวลาและจำนวนรอบการวิเคราะห์ CAE Simulation ก่อนอนุมัติแบบแม่พิมพ์กับลูกค้า\", \"kqi\": \"\", \"qwp\": \"QWP-T13\", \"roi\": \"\", \"data\": 3, \"dept\": \"TRT Mold\", \"name\": \"AI ช่วยวิเคราะห์และ Optimize เงื่อนไขการฉีดขึ้นรูปจากผล CAE Simulation (ออกแบบแม่พิมพ์ใหม่)\", \"risk\": 4, \"owner\": \"\", \"risks\": \"AI อาจแนะนำ Condition การฉีดที่ยังไม่ผ่านการพิสูจน์จริง ต้องมีวิศวกรตรวจสอบและทดสอบยืนยันผลก่อนนำไปใช้จริงทุกครั้งในช่วงแรกของการใช้งาน\", \"users\": \"\", \"aiType\": \"numeric\", \"impact\": 4, \"output\": \"AI ช่วยวิเคราะห์และสรุปผลจากตัวแปร Simulation (Material Specification, 3D Mold Design, Injection Condition) พร้อมช่วย Optimize Condition การฉีดขึ้นรูปให้ได้ประสิทธิภาพสูงสุด\", \"control\": \"\", \"latency\": \"แบบกลุ่ม/ไม่เร่งด่วน (Batch)\", \"problem\": \"กระบวนการออกแบบแม่พิมพ์ปัจจุบันต้องตรวจสอบและประเมินแบบแม่พิมพ์หลายรูปแบบด้วยวิธี Trial & Error ผ่าน CAE Simulation ก่อนอนุมัติ concept mold design ให้ลูกค้า ทำให้ใช้เวลานานและต้องอาศัยวิศวกรวิเคราะห์ผล Simulation จำนวนมากด้วยตนเอง\", \"refStep\": \"FS-A40-002-T (A) Work Instruction การออกแบบแม่พิมพ์ขึ้นรูปพลาสติก\", \"approver\": \"\", \"hardware\": \"\", \"language\": \"\", \"solution\": \"จำลองการฉีดขึ้นรูปชิ้นงาน (CAE Simulation) ด้วยคอมพิวเตอร์ เพื่อตรวจสอบและประเมินการทำงานของแม่พิมพ์จากการออกแบบหลายแบบ (Trial & Error) แทนการขึ้นฉีดแม่พิมพ์จริง แล้วนำข้อมูล Parameter และ Condition การฉีดไปให้ลูกค้า approve concept mold design โดยวิศวกรวิเคราะห์ผลด้วยตัวเองทั้งหมด\", \"attachRef\": \"TRT MOLD 2026-06-24 AI Transformation Plan ห้อง ดร.วีรพจน์.xlsx (sheet: สรุป AI-Transform-Plan (ปี2026))\", \"resources\": \"\", \"preparedBy\": \"\", \"feasibility\": 2, \"availability\": \"เวลาทำการ 8x5 (จันทร์-ศุกร์)\", \"redesignDesc\": \"AI ช่วยวิเคราะห์และสรุปผลจากตัวแปร Simulation (Material Specification, 3D Mold Design, Injection Condition) พร้อมช่วย Optimize Condition การฉีดขึ้นรูปให้ได้ประสิทธิภาพสูงสุด\", \"recommendation\": \"\", \"dataSensitivity\": \"ลับ (Confidential)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_1788934146507_2604','MOLDING – ติดตามแผนการผลิต MPS/PLN แบบ Real-time','MOLDING','{\"id\": \"uc_1788934146507_2604\", \"kpi\": \"\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"\", \"data\": 4, \"dept\": \"MOLDING\", \"name\": \"MOLDING – ติดตามแผนการผลิต MPS/PLN แบบ Real-time\", \"risk\": 2, \"owner\": \"\", \"risks\": \"\", \"users\": \"\", \"aiType\": \"agent\", \"impact\": 3, \"latency\": \"\", \"refStep\": \"รับแผน MPS และปรับกำลังคนแต่ละกะให้สอดคล้องกับ MPS\\nเตรียมชุดเอกสารสำหรับบันทึกการผลิต / จัดวางตัวบุคคลในการผลิตให้สอดคล้องกับ SKILLMAP (ล่วงหน้า)\", \"approver\": \"\", \"hardware\": \"\", \"language\": \"\", \"solution\": \"ตรวจสอบแผน MPS ที่ Google Sheet\\nตรวจสอบแผนการผลิตที่จะขึ้นใหม่ (ล่วงหน้า)\\nตรวจสอบกำลังคนที่จะใช้ในแต่ละวัน (ล่วงหน้า)\\nจัดทำตารางการผลิตประจำวัน\\nนำเลขที่ PLN ของแผนที่ขึ้นใหม่มาจัดทำเอกสาร\\n- CHECK SHEET การ SET UP งานก่อนผลิต\\n- ใบรายงานติดตามสถานะการผลิต\\n- ตารางสรุปการรับ COMPOUND-C\\n- เอกสารจ่ายส่วนประกอบ DETALLS PACKING\\n- ใบเบิกถุงพลาสติก/กล่องกระดาษ/ชิ้นส่วนประกอบ\\n- ใบสั่งจ่ายและติดตั้งแม่พิมพ์\", \"attachRef\": \"\", \"resources\": \"\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 4, \"availability\": \"\", \"redesignDesc\": \"Real Time Link MPS & PLN Index\\nReal Time Show แผนการผลิตที่จะขึ้นใหม่ (ล่วงหน้า)\\nReal Time Show กำลังคนที่จะใช้ในแต่ละวัน (ล่วงหน้า)\\nReal Time Show ตารางการผลิตประจำวัน\\nGenerate ทุกเอกสารจากการลงข้อมูลครั้งเดียว\\n- ERP (Created)\", \"dataAvailable\": \"MPS & PLN INDEX ใน Google Sheet\", \"recommendation\": \"\", \"dataSensitivity\": \"\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_1788938855540_9229','MOLDING – จัดคนเข้าเครื่องจักรอัตโนมัติตาม Skill Map','MOLDING','{\"id\": \"uc_1788938855540_9229\", \"kpi\": \"\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"\", \"data\": 3, \"dept\": \"MOLDING\", \"name\": \"MOLDING – จัดคนเข้าเครื่องจักรอัตโนมัติตาม Skill Map\", \"risk\": 3, \"owner\": \"\", \"risks\": \"\", \"users\": \"\", \"aiType\": \"\", \"impact\": 3, \"latency\": \"\", \"refStep\": \"จัดวางตัวบุคคลเพื่อผลิตให้สอดคล้องกับ SKILLMAP\", \"approver\": \"\", \"hardware\": \"\", \"language\": \"\", \"solution\": \"1.ตรวจสอบยางที่รับเข้าและคงเหลือ จากไฟล์ Compound Status (Auto)\\n2.ตรวจสอบพนักงานที่มี (หลังสแกนชื่อเข้างาน)\\n3.ตรวจสอบแผนที่ขึ้นผลิต ประจำวันจากไฟล์ Shop Mps\\n4.ตรวจสอบงาน Order ที่ต้องส่ง (Stock ไม่พอ/ไม่มี)\\n5.ตัดสินเลือกแผนที่จะทำการเดิน\\n   - ยางใกล้หมดอายุ + งาน Order ต้องส่ง (Piority แรก)\\n   - ยางใน Stock เหลือเยอะ\\n6.จัดวางตัวบุคคลในการผลิตให้สอดคล้องกับ SKILLMAP (ตามที่บันทึกในประวัติ)\", \"attachRef\": \"\", \"resources\": \"\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 3, \"availability\": \"\", \"redesignDesc\": \"ขั้นตอนการทำงานใหม่\\n1.เปิดไฟล์จัดคนอัตโนมัติ\\n2.เลือกวันที่\\n3.ไฟล์ทำการแสดงรายชื่อของพนักงาน (อัตโนมัติ) ตามเงื่อนไข (ยางใกล้หมดอายุ/Stock เหลือมากได้จัดคนก่อน, ไม่แสดงชื่อคนที่ลา-ขาด, เลือกคน Skill สูงสุดก่อน)\\n4.หัวหน้างานปรับ Adjust คนตามความเหมาะสม\\n\\n(รายละเอียดจาก Excel: เตรียม SKILL LEVEL ของพนักงานผ่าน Google Form → จัด BUFFER STOCK/การมาทำงาน → จัดสำคัญแผนที่ต้องเดิน → จัดคนเข้าเครื่องตามลำดับ Skill โดยคนที่ขาด/ลาจะไม่ถูกเลือก และจะมี Line แจ้งเตือนหากกำลังคนไม่ครบตาม MPS)\", \"dataAvailable\": \"ไฟล์ Compound Status\\nบันทึกการเข้างาน (แสกนชื่อเข้างาน)\\nไฟล์ Shop MPS / Sheet แผนที่ Run\\nใบจัดคน\\nไฟล์บันทึกประวัติ Part Training\", \"recommendation\": \"\", \"dataSensitivity\": \"\"}','2026-09-09 07:28:36','2026-09-09 07:28:36'),('uc_1788938916088_8314','NPD – ระบบช่วยออกแบบกระบวนการผลิตใหม่ด้วย AI (Estimate Process)','NPD','{\"id\": \"uc_1788938916088_8314\", \"kpi\": \"\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"\", \"data\": 3, \"dept\": \"NPD\", \"name\": \"NPD – ระบบช่วยออกแบบกระบวนการผลิตใหม่ด้วย AI (Estimate Process)\", \"risk\": 3, \"owner\": \"\", \"risks\": \"\", \"users\": \"\", \"aiType\": \"\", \"impact\": 4, \"latency\": \"\", \"refStep\": \"ออกแบบกระบวนการผลิต\\n* ออกแบบการขึ้นรูป, ปลดชิ้นงาน, ตกแต่ง\", \"approver\": \"\", \"hardware\": \"\", \"language\": \"\", \"solution\": \"1.รวบรวมข้อมูลของผลิตภัณฑ์ ตามขั้นตอนใน Check Sheet\\n2.นำข้อมูลที่รวบรวมได้มากรอกข้อมูลในไฟล์ Estimated Process\\n3.ไฟล์แสดงผลของ Process การผลิตที่ควรเลือก (รูปแบบการผลิต, จำนวน Cav., รูปแบบการเปิดแม่พิมพ์, รูปแบบการตกแต่ง, วิธีการบรรจุ, เป้าหมายการผลิต/ชม. (Curing Time, Loading+Release Time, Man Hour), ข้อมูล Material (Net/Flash Weight))\\n4.นำข้อมูล Guide line จากข้อ 3 มาออกแบบ Concept Design (อย่างละเอียด) และ Estimate Cost 2 อีกครั้ง\\n5.นำ Concept Design จากข้อ 4 สั่งผลิตตามที่ออกแบบไว้\\n\\nหมายเหตุ: File Estimate Process แม่นยำ 70%, ข้อมูลเป็น Offline Update, หลักการทำงานเป็นแบบ Cut off process อาจคลาดเคลื่อนเมื่อข้อมูลอยู่ชิดขอบช่วงที่กำหนด\", \"attachRef\": \"\", \"resources\": \"\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 4, \"availability\": \"\", \"redesignDesc\": \"Program ช่วยออกแบบการผลิต\\n1.INPUT DATA ข้อมูลของสินค้า\\n2.Program นำ INPUT DATA ไปประมวลผลรวมกับ MODEL AI ที่ TRAINING\\n3.ไฟล์แสดงผลของ Process การผลิตที่ควรเลือก (แสดง % Prediction ด้วย)\\n4.นำข้อมูล Guide line มาออกแบบ Concept Design และ Estimate Cost 2 อีกครั้ง\\n5.นำ Concept Design สั่งผลิตตามที่ออกแบบไว้\\n\\n(สรุปจาก Excel: เก็บข้อมูลการขึ้นรูปจากสินค้าที่มีผลการผลิตดี (Performance & Good Rate สูง ใช้คนงานน้อย) ผ่าน Google Form เพื่อ Train Model ด้วย Decision Tree/Naive Bayes/SVM บน Google Colab จากนั้นทำ UX/UI สำหรับการหน้อนข้อมูลเข้า/แสดงผล)\", \"dataAvailable\": \"Product Quality Check Sheet\\nFile Process Design Sheet\\nCost 2 และใบสั่งผลิตแม่พิมพ์และ Tooling\", \"recommendation\": \"\", \"dataSensitivity\": \"\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_1789004435820_1031','CNC IoT–ERP Integration Project — เชื่อมข้อมูลเครื่อง CNC ผ่าน IoT เข้าสู่ระบบ ERP','TRT MOLD','{\"id\": \"uc_1789004435820_1031\", \"kpi\": \"Machine status accuracy ≥ 95%, Actual time accuracy คลาดเคลื่อนไม่เกิน ±1%, Data availability ≥ 99%, Work Order matching 100%, Alarm capture ครบตาม Test set\", \"kqi\": \"\", \"qwp\": \"\", \"roi\": \"เพิ่มความแม่นยำของต้นทุนแม่พิมพ์และการเสนอราคา ลดความคลาดเคลื่อนระหว่างต้นทุนมาตรฐานกับต้นทุนจริง เป็นฐานข้อมูลสำหรับขยายสู่ Smart Manufacturing / PM-PdM ในอนาคต — ยังไม่มีตัวเลข ROI เป็นตัวเงินที่เอกสารระบุ\", \"data\": 2, \"dept\": \"TRT MOLD\", \"name\": \"CNC IoT–ERP Integration Project — เชื่อมข้อมูลเครื่อง CNC ผ่าน IoT เข้าสู่ระบบ ERP\", \"risk\": 4, \"owner\": \"ฝ่ายผลิตแม่พิมพ์ (Mold Production) / ERP Key User\", \"risks\": \"ห้ามแก้ไข Safety Interlock/PLC Ladder, ห้ามเปิด Remote Desktop เข้า CNC โดยตรง, ห้ามเขียน Parameter/Program กลับเครื่องในขอบเขต Pilot; ต้องแยกสถานะ Offline (Network/Gateway ขัดข้อง) ออกจาก Downtime จริงของเครื่องให้ชัดเจน\", \"users\": \"\", \"aiType\": \"numeric\", \"impact\": 4, \"latency\": \"\", \"refStep\": \"\", \"approver\": \"คณะผู้บริหาร S.K. Polymer\", \"hardware\": \"IoT Gateway, Industrial Switch/Firewall, Server + UPS, IoT Database (Time-series), Dashboard — เลือกตามผลสำรวจ Controller/Network ของเครื่อง CNC ที่เลือก\", \"language\": \"\", \"solution\": \"ปัจจุบันการประเมินต้นทุนงานแม่พิมพ์อาศัย CAM Estimated Time และสมมติฐานมาตรฐานของเครื่องจักร ยังไม่ได้ใช้เวลาที่เกิดขึ้นจริงจาก Setup, Cutting, Idle, Alarm และ Downtime จึงทำให้ต้นทุนที่รายงานคลาดเคลื่อนจากความเป็นจริง\", \"attachRef\": \"AI Transformation Plan-RD CENTER.xlsx / CNC_IoT_ERP_Integration_Project_Proposal_TH_TRT MOLD.docx\", \"resources\": \"ทีมข้ามสายงาน: Project Sponsor/PM, ฝ่ายผลิตแม่พิมพ์, IT/OT, ERP Key User, Vendor — ระยะเวลา Pilot ประมาณ 20 สัปดาห์ (12 เฟส) รวม Pilot Run ใช้งานจริง 30 วัน เริ่มจากเครื่อง CNC 1 เครื่อง\", \"attachment\": null, \"preparedBy\": \"\", \"feasibility\": 3, \"availability\": \"เกือบตลอดเวลา 24x7 (99.5%)\", \"redesignDesc\": \"เมื่อนำ IoT Gateway มาเชื่อมเครื่อง CNC แบบ Read-only แล้ว ระบบจะคำนวณ Actual Production Time (Cutting/Setup/Idle/Alarm/Downtime) แบบเรียลไทม์ สรุปผลต่อ Job แล้วส่งกลับเข้า ERP อัตโนมัติ ทำให้ต้นทุนแม่พิมพ์และการเสนอราคาแม่นยำขึ้น พร้อมเก็บข้อมูลไว้ต่อยอดสำหรับ Preventive/Predictive Maintenance ในอนาคต\", \"dataAvailable\": \"ข้อมูล Work Order / Mold Job จากระบบ ERP, ข้อมูลสถานะ/สัญญาณจากเครื่อง CNC (Power, Mode, Cycle, Spindle, Alarm) ผ่าน OPC UA/MTConnect/Vendor API และข้อมูลยืนยันจาก Operator (Job, Downtime reason, Good/Rework) — ดูแลโดยฝ่ายผลิตแม่พิมพ์และ IT/OT\", \"recommendation\": \"เริ่ม Pilot 1 เครื่องแบบ Read-only ก่อน (20 สัปดาห์ รวม Pilot Run 30 วัน) เมื่อผ่านเกณฑ์ UAT จึงเสนอแผนขยายผล (Rollout 5 Waves) ไปยังเครื่อง CNC อื่น\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-10 01:40:35','2026-09-10 01:58:10'),('uc_ee_1','AI Vision ตรวจสอบการเข้าประกบแม่พิมพ์ (Mold Clamping Safety) เครื่อง Compression/Injection','Production','{\"id\": \"uc_ee_1\", \"kpi\": \"ลดจำนวนครั้งแม่พิมพ์เสียหายจากการเข้าประกบผิดพลาดลง 80%, ไม่มีอุบัติเหตุจากจุดนี้\", \"kqi\": \"% GOOD RATE > 98%, % PERFORMANCE > 95%\", \"qwp\": \"QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01)\", \"roi\": \"คาดคืนทุนภายใน 10-12 เดือนจากการลดค่าซ่อมแม่พิมพ์และเวลาหยุดเครื่อง\", \"data\": 2, \"dept\": \"Production\", \"name\": \"AI Vision ตรวจสอบการเข้าประกบแม่พิมพ์ (Mold Clamping Safety) เครื่อง Compression/Injection\", \"risk\": 5, \"owner\": \"ผจก.ส่วนผลิต Molding Plant\", \"risks\": \"ต้องเก็บวิดีโอการเคลื่อนที่ของแม่พิมพ์ทั้งสภาวะปกติ/ผิดปกติให้เพียงพอสำหรับเทรนโมเดล และมีความเสี่ยงด้านความปลอดภัยหากระบบแจ้งเตือนผิดพลาด (false negative) จึงต้องมีมาตรการ Fail-safe ควบคู่กับคนเสมอ\", \"score\": 62, \"users\": \"\", \"aiType\": \"vision\", \"impact\": 4, \"output\": \"แจ้งเตือนอัตโนมัติ + หยุดเครื่องทันทีเมื่อพบความผิดปกติในการเข้าประกบแม่พิมพ์ พร้อมบันทึกวิดีโอ/log เหตุการณ์\", \"control\": \"รายละเอียดที่ทำการตรวจสอบต้องผ่านทุกหัวข้อที่กำหนด\", \"latency\": \"ทันที (< 1 วินาที)\", \"problem\": \"ขั้นตอนขึ้นรูป (ทั้งเครื่อง Compression และ Injection) พนักงานกด Start ให้เครื่องทำงานอัตโนมัติ แล้วต้องเฝ้าดูการเข้าประกบของแม่พิมพ์ด้วยสายตาเพื่อความปลอดภัย หากตรวจไม่ทันหรือพลาด อาจทำให้แม่พิมพ์เสียหายหรือเกิดอุบัติเหตุ ผลลัพธ์ขึ้นกับความชำนาญของพนักงานแต่ละคนและไม่มีการบันทึกหลักฐานย้อนหลัง\", \"refStep\": \"ขั้นตอนที่ 4 ผลิตและควบคุม (WI-A07-001 การ SET UP และทวนสอบกระบวนการก่อนการผลิต)\", \"approver\": \"ผจก.ส่วนผลิต Molding Plant\", \"hardware\": \"กล้อง Industrial + Edge GPU ติดตั้งหน้าเครื่องขึ้นรูปทุกเครื่อง ร่วมกับเซนเซอร์วัดแรงดัน (Pressure Sensor)\", \"language\": \"Thai\", \"priority\": \"med\", \"solution\": \"พนักงานเฝ้าดูด้วยตาเปล่าและกดหยุดเครื่องเองเมื่อสังเกตความผิดปกติ ไม่มีระบบแจ้งเตือนหรือบันทึกอัตโนมัติ อ้างอิงตาม WI-A07-001 (การ SET UP และทวนสอบกระบวนการก่อนการผลิต)\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Prod, ขั้นตอน 6.1 ข้อ 2.3)\", \"resources\": \"ทีม AI Dev 2 คน + ทีม Automation/Eng., ระยะเวลา 12 สัปดาห์, งบประมาณ ~500,000 บาท (รวมกล้องและเซนเซอร์)\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 3, \"availability\": \"ตลอดเวลา 24x7 (99.9%+)\", \"redesignDesc\": \"แจ้งเตือนอัตโนมัติ + หยุดเครื่องทันทีเมื่อพบความผิดปกติในการเข้าประกบแม่พิมพ์ พร้อมบันทึกวิดีโอ/log เหตุการณ์\", \"recommendation\": \"นำร่องที่เครื่อง Compression ที่มีประวัติแม่พิมพ์เสียหายบ่อยที่สุดก่อน ใช้ 2 ระบบร่วมกันคือกล้องจดจำการเคลื่อนที่ของแม่พิมพ์ (ระยะทาง/เวลา) และระบบตรวจ Pressure ที่ระยะต่างๆ\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_ee_2','หุ่นยนต์หยิบวาง Compound เข้าแม่พิมพ์ และเคลื่อนย้ายชิ้นงานไปจุดตกแต่ง (Deflashing)','Production','{\"id\": \"uc_ee_2\", \"kpi\": \"ลดอุบัติเหตุ/บาดเจ็บจากการหยิบจับที่ร้อนลง 100%, เพิ่มความสม่ำเสมอของตำแหน่งวาง Compound\", \"kqi\": \"% GOOD RATE > 98%, % PERFORMANCE > 95%\", \"qwp\": \"QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01)\", \"roi\": \"คาดคืนทุนภายใน 18-24 เดือนจากการลดของเสียจากตำแหน่งวางไม่สม่ำเสมอ และลดแรงงานจุดนี้\", \"data\": 2, \"dept\": \"Production\", \"name\": \"หุ่นยนต์หยิบวาง Compound เข้าแม่พิมพ์ และเคลื่อนย้ายชิ้นงานไปจุดตกแต่ง (Deflashing)\", \"risk\": 3, \"owner\": \"หัวหน้าหน่วยผลิต Molding Plant\", \"risks\": \"ต้องออกแบบ Layout, เส้นทางเคลื่อนที่ และอุปกรณ์จับยึดให้เหมาะกับ Compound/ชิ้นงานแต่ละรุ่น การเปลี่ยนรุ่นผลิตบ่อยอาจทำให้ต้อง Retool/Retrain บ่อย\", \"score\": 67, \"users\": \"\", \"aiType\": \"vision\", \"impact\": 4, \"output\": \"หุ่นยนต์วาง Compound เข้าแม่พิมพ์ และเคลื่อนย้ายชิ้นงานไปจุดตกแต่งโดยอัตโนมัติ ลดการใช้มือคน\", \"control\": \"มาตรฐานถูกต้องและอัปเดตเป็นปัจจุบัน\", \"latency\": \"เร็ว (1-3 วินาที)\", \"problem\": \"พนักงานใช้มือวางยาง Compound เข้าแม่พิมพ์ (บางจุดใช้ Jig บางจุดไม่ใช้) และใช้มือเคลื่อนย้ายชิ้นงานจากเครื่องขึ้นรูปไปยังจุดตกแต่ง (Deflashing) ทำให้เสี่ยงบาดเจ็บจากความร้อน/แรงกด และควบคุมความสม่ำเสมอของตำแหน่งวางได้ยาก\", \"refStep\": \"ขั้นตอนที่ 4 ผลิตและควบคุม (MOLDING WORKING STANDARD FS-R2-003)\", \"approver\": \"ผจก.ส่วนผลิต Molding Plant\", \"hardware\": \"แขนกล Robot Arm พร้อมกล้อง Vision-guided สำหรับหยิบจับ Compound และ Jig/Fixture เฉพาะสำหรับแต่ละรุ่นแม่พิมพ์\", \"language\": \"Thai\", \"priority\": \"med\", \"solution\": \"พนักงานวาง Compound ด้วยมือ และเดินยกชิ้นงานไปแต่งเองทุกรอบการผลิต ไม่มีระบบเคลื่อนย้ายอัตโนมัติ\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Prod, ขั้นตอน 6.1 ข้อ 1.2 และ 6.1 ข้อ 4.1 ตกแต่งด้วย Deflashing)\", \"resources\": \"ทีม Automation/Robotics 2-3 คน + ทีม AI Dev 1 คน, ระยะเวลา 16 สัปดาห์, งบประมาณ ~1,200,000 บาท (รวมแขนกลและ Jig)\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 2, \"availability\": \"ตลอดเวลา 24x7 (99.9%+)\", \"redesignDesc\": \"หุ่นยนต์วาง Compound เข้าแม่พิมพ์ และเคลื่อนย้ายชิ้นงานไปจุดตกแต่งโดยอัตโนมัติ ลดการใช้มือคน\", \"recommendation\": \"นำร่องกับรุ่นแม่พิมพ์ที่ผลิตซ้ำปริมาณมากและ Layout คงที่ก่อน แล้วค่อยขยายไปรุ่นที่เปลี่ยนบ่อย\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_ee_3','AI จัดสรรกำลังคนตาม Skill Matrix อัตโนมัติ (AI-Driven Manpower Allocation)','Production','{\"id\": \"uc_ee_3\", \"kpi\": \"ลด NG Rate จากพนักงานทักษะไม่ตรงงานลง, เพิ่ม % Performance worker > 95%, ลดเวลาจัดคนของหัวหน้างานต่อกะ\", \"kqi\": \"จำนวนรายการสินค้า NC ในรอบเดือน, % PERFORMANCE WORKER > 95%\", \"qwp\": \"QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01) + ตารางบันทึกการสอนงาน FS-H2-023\", \"roi\": \"คาดคืนทุนภายใน 6-9 เดือนจากการลดของเสียและเวลาที่หัวหน้างานใช้จัดคนต่อวัน\", \"data\": 3, \"dept\": \"Production\", \"name\": \"AI จัดสรรกำลังคนตาม Skill Matrix อัตโนมัติ (AI-Driven Manpower Allocation)\", \"risk\": 3, \"owner\": \"หัวหน้างาน Molding Plant\", \"risks\": \"ต้องมี Skill Matrix Database และ Job Master Data ที่ถูกต้อง ครบถ้วน และอัปเดตสม่ำเสมอ มิฉะนั้นระบบจะจัดคนผิดพลาด ต้องมี Fallback ให้หัวหน้างานปรับแก้ก่อนเริ่มงานเสมอ\", \"score\": 77, \"users\": \"\", \"aiType\": \"recommend\", \"impact\": 3, \"output\": \"ตารางจัดสรรพนักงานประจำเครื่องจักร/แม่พิมพ์รายกะ พร้อมเหตุผลประกอบ ให้หัวหน้างานตรวจสอบ/ปรับแก้ก่อนเริ่มงาน\", \"control\": \"พนักงานที่ขึ้นปฏิบัติงานทุกคนต้องผ่านการ OJT และบันทึกผล\", \"latency\": \"ปานกลาง (3-10 วินาที)\", \"problem\": \"หัวหน้างานใช้ดุลพินิจจัดคนลงหน้างานแบบ Manual โดยอ้างอิงข้อมูลการ Fix คน Fix เครื่อง และ Part Training ที่ผูกไว้ด้วย Excel ทำให้เสี่ยงจัดพนักงานทักษะไม่ตรงกับความยากของแม่พิมพ์ จนเกิดงานเสีย (NG) และไม่มีการ Optimize ให้เกิดประสิทธิภาพสูงสุด\", \"refStep\": \"ขั้นตอนที่ 4.9 (พนักงานที่ขึ้นปฏิบัติงานทุกคนต้องผ่านการ OJT และบันทึกผล)\", \"approver\": \"ผจก.ส่วนผลิต Molding Plant\", \"hardware\": \"เริ่มต้นแบบ Low-cost: Python (PuLP/SciPy.optimize/DEAP) + Google Sheets/Power Apps เป็น Dashboard ก่อน ค่อยขยับสู่ MILP + ML (XGBoost/Random Forest) บน Cloud (AWS SageMaker/Azure ML) เมื่อพร้อม\", \"language\": \"Thai\", \"priority\": \"high\", \"solution\": \"หัวหน้างานจัดคนแบบ Manual จากตาราง Fix คน Fix เครื่อง, ข้อมูล Part Training, ข้อมูลการมาทำงานจาก Payroll และประวัติผลงานพนักงานรายบุคคล โดยไม่มีระบบช่วยคำนวณหรือแจ้งเตือน\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Man Alocation1/2/3 — AI-Driven Allocation Workflow)\", \"resources\": \"ทีม AI/Data 2 คน, ระยะเวลา 10-14 สัปดาห์ (เฟส Low-cost), งบประมาณ ~300,000-800,000 บาท ขึ้นกับระดับที่เลือก (Low-cost / Enterprise / Commercial)\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 3, \"availability\": \"เวลาทำการ 8x5 (จันทร์-ศุกร์)\", \"redesignDesc\": \"ตารางจัดสรรพนักงานประจำเครื่องจักร/แม่พิมพ์รายกะ พร้อมเหตุผลประกอบ ให้หัวหน้างานตรวจสอบ/ปรับแก้ก่อนเริ่มงาน\", \"dataAvailable\": \"ไฟล์ Compound Status\\nบันทึกการเข้างาน (แสกนชื่อเข้างาน)\\nไฟล์ Shop MPS / Sheet แผนที่ Run\\nใบจัดคน\\nไฟล์บันทึกประวัติ Part Training\", \"recommendation\": \"เริ่มจากระดับ Low-Cost & Functional (Rule-Based + Linear Programming/Genetic Algorithm บน Python + Google Sheets/Make.com แบบ No-Code) ก่อนเป็น Quick Win แล้วค่อยพิจารณาระดับ Enterprise (MILP + ML พยากรณ์ NG Rate) เมื่อผลลัพธ์ชัดเจน\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_ee_4','Auto Inspection ตรวจสอบคุณภาพชิ้นงานด้วย Machine Learning (แยกสินค้าดี/เสีย)','Quality','{\"id\": \"uc_ee_4\", \"kpi\": \"ลดจำนวนสินค้า NC หลุดออกไปยังลูกค้าให้เป็น 0 ครั้ง/เดือน, ลดเวลาตรวจสอบต่อชิ้นลง\", \"kqi\": \"% GOOD RATE > 98%, % PERFORMANCE > 95%, จำนวนครั้งที่ลูกค้า Reject 0 ครั้ง/เดือน\", \"qwp\": \"QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01)\", \"roi\": \"คาดคืนทุนภายใน 8-10 เดือนจากการลดของเสียหลุดและลดแรงงานตรวจสอบ\", \"data\": 2, \"dept\": \"Quality\", \"name\": \"Auto Inspection ตรวจสอบคุณภาพชิ้นงานด้วย Machine Learning (แยกสินค้าดี/เสีย)\", \"risk\": 2, \"owner\": \"ส่วนประกันคุณภาพ (QA)\", \"risks\": \"ต้องเก็บภาพตัวอย่างสินค้าดีและเสียให้ครอบคลุมทุกรูปแบบตำหนิ (defect type) เพื่อเทรนโมเดลให้แม่นยำเพียงพอ และต้องมีขั้นตอนสุ่มตรวจซ้ำโดยคนในช่วงแรกเพื่อยืนยันความแม่นยำ\", \"score\": 70, \"users\": \"\", \"aiType\": \"vision\", \"impact\": 4, \"output\": \"ผลตรวจสอบสินค้าดี/เสียแบบอัตโนมัติ พร้อมภาพหลักฐานและสถิติของเสียตามรุ่น\", \"control\": \"เมื่อพบปัญหาของเสียหรือ Performance ให้ดำเนินการแก้ไขตามขั้นตอนปฏิบัติใน MOLDING WORKING STD.\", \"latency\": \"เร็ว (1-3 วินาที)\", \"problem\": \"การตรวจสอบคุณภาพชิ้นงานหลังขึ้นรูปใช้การตรวจด้วยสายตาของพนักงาน (Visual Inspection) ทำให้ผลลัพธ์ไม่คงที่ ขึ้นกับความล้าและความชำนาญของผู้ตรวจแต่ละคน และไม่มีข้อมูลภาพเก็บไว้ตรวจสอบย้อนหลัง\", \"refStep\": \"ขั้นตอนที่ 5 (ใบรายงานการผลิต(ขึ้นรูปยาง) FS-F1-011)\", \"approver\": \"ผจก.ส่วนประกันคุณภาพ\", \"hardware\": \"เครื่อง Auto Inspection พร้อมกล้อง Machine Vision + โมเดล Machine Learning สำหรับจำแนกสินค้าดี/เสีย\", \"language\": \"Thai\", \"priority\": \"med\", \"solution\": \"พนักงาน QA เดินตรวจสอบหน้างานด้วยสายตาและวัดด้วยตัวเอง ตามใบรายงานการผลิต (ขึ้นรูปยาง) FS-F1-011\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Prod, ขั้นตอน 6.1 ข้อ 5.1)\", \"resources\": \"ทีม AI Dev 2 คน + ทีม QA, ระยะเวลา 10 สัปดาห์, งบประมาณ ~400,000 บาท (รวมกล้องและชุดเทรนโมเดล)\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 4, \"availability\": \"ตลอดเวลา 24x7 (99.9%+)\", \"redesignDesc\": \"ผลตรวจสอบสินค้าดี/เสียแบบอัตโนมัติ พร้อมภาพหลักฐานและสถิติของเสียตามรุ่น\", \"recommendation\": \"นำร่องกับสินค้ารุ่นที่มีประวัติของเสียซ้ำบ่อยและตำหนิสังเกตได้ชัดด้วยภาพก่อน แล้วขยายไปรุ่นอื่น\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_ee_5','Big Data Dashboard วิเคราะห์และปิด LOT การผลิตอัตโนมัติ (Close Lot Analytics)','Production','{\"id\": \"uc_ee_5\", \"kpi\": \"ลดเวลาที่ใช้เตรียมข้อมูลก่อนประชุม Close Lot ลง 70%, ทราบกำไร/ต้นทุนต่อ Lot แบบ Real-time\", \"kqi\": \"% สินค้าโอนขึ้นคลัง >98%, % งานจบตามแผน >98%, % OEE >80%\", \"qwp\": \"QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01)\", \"roi\": \"คาดคืนทุนภายใน 12 เดือนจากเวลาที่ประหยัดได้ของทีม IO และการตัดสินใจปรับราคาที่เร็วขึ้น\", \"data\": 3, \"dept\": \"Production\", \"name\": \"Big Data Dashboard วิเคราะห์และปิด LOT การผลิตอัตโนมัติ (Close Lot Analytics)\", \"risk\": 4, \"owner\": \"IO / ทีมวางแผนการผลิต\", \"risks\": \"ต้องเชื่อมข้อมูลจากหลายระบบที่อาจมีรูปแบบไม่ตรงกัน (ERP, MES, QA, Payroll) และต้องกำหนดเจ้าของข้อมูลแต่ละส่วนให้ชัดเจนเพื่อความถูกต้องของตัวเลขต้นทุน\", \"score\": 70, \"users\": \"\", \"aiType\": \"numeric\", \"impact\": 4, \"output\": \"Dashboard สรุปผลการผลิต ต้นทุน และสถานะความพร้อมของ Mold/Tooling แบบ Real-time สำหรับที่ประชุม Close Lot\", \"control\": \"ได้มาตรการในการแก้ไขปัญหาที่เกิดขึ้นและแก้ไขเสร็จก่อน Lot ผลิตถัดไป\", \"latency\": \"ปานกลาง (3-10 วินาที)\", \"problem\": \"การประชุม Close Lot Meeting ต้องรวบรวมข้อมูลต้นทุน, % Yield rate, % Cost, ประวัติ NC/CCR และ Last Mold/Last shot จากหลายแหล่งด้วยมือ ทำให้ใช้เวลานานและไม่สามารถประเมินกำไรของแต่ละ Lot แบบ Real-time ได้\", \"refStep\": \"ขั้นตอนที่ 7-9 (สรุปจบแผนการผลิตและ Close Lot Meeting, WI-A07-002)\", \"approver\": \"ผจก.ส่วนผลิต Molding Plant\", \"hardware\": \"ระบบ Data Warehouse/Big Data เชื่อมข้อมูลจากหลายระบบ (ERP, MES, QA) + Dashboard วิเคราะห์ Real-time\", \"language\": \"Thai\", \"priority\": \"med\", \"solution\": \"เจ้าหน้าที่ IO รวบรวมข้อมูลการผลิตมาคิดต้นทุนและบันทึกข้อมูลด้วยมือ แล้วนำเข้าที่ประชุม Close Lot Meeting เพื่อพิจารณาผลทีละหัวข้อ\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Prod, ขั้นตอน 6.1 ข้อ 9 Close Lot Meeting)\", \"resources\": \"ทีม Data Engineer 2 คน + ทีม IO, ระยะเวลา 12 สัปดาห์, งบประมาณ ~600,000 บาท\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 2, \"availability\": \"เวลาทำการ 8x5 (จันทร์-ศุกร์)\", \"redesignDesc\": \"Dashboard สรุปผลการผลิต ต้นทุน และสถานะความพร้อมของ Mold/Tooling แบบ Real-time สำหรับที่ประชุม Close Lot\", \"recommendation\": \"เริ่มเชื่อมข้อมูล % Yield rate และ % Cost ก่อนเป็นชุดแรก แล้วค่อยเพิ่มประวัติ NC/CCR และ Last Mold/Last shot\", \"dataSensitivity\": \"ลับ (Confidential)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_ee_6','ระบบ Barcode รับสินค้าเข้าคลังอัตโนมัติ (แทนการนับด้วยคน)','Production','{\"id\": \"uc_ee_6\", \"kpi\": \"ลดข้อผิดพลาดจากการนับสินค้าด้วยมือลง 90%, ลดเวลารับสินค้าเข้าคลังต่อ Lot\", \"kqi\": \"จำนวนครั้งที่ลูกค้า Reject 0 ครั้ง/เดือน\", \"qwp\": \"QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01)\", \"roi\": \"คาดคืนทุนภายใน 6 เดือนจากเวลาที่ประหยัดได้และลดข้อผิดพลาดการนับ\", \"data\": 5, \"dept\": \"Production\", \"name\": \"ระบบ Barcode รับสินค้าเข้าคลังอัตโนมัติ (แทนการนับด้วยคน)\", \"risk\": 1, \"owner\": \"\", \"risks\": \"ต้องติดฉลาก Barcode ให้ครบทุกบรรจุภัณฑ์ตั้งแต่ต้นทาง และมีแผนสำรอง (manual) กรณีเครื่องสแกนขัดข้อง\", \"score\": 76, \"users\": \"\", \"aiType\": \"repetitive\", \"impact\": 3, \"output\": \"ยอดรับสินค้าเข้าคลังที่บันทึกอัตโนมัติจากการสแกน Barcode พร้อมรายงานส่วนต่าง (ถ้ามี) แบบ Real-time\", \"control\": \"ส่งมอบสินค้าได้ตามคุณภาพ ตามมาตรฐานที่กำหนด ไม่โดน NC\", \"latency\": \"ทันที (< 1 วินาที)\", \"problem\": \"พนักงานนำสินค้าที่บรรจุเสร็จมาส่งที่จุดพักก่อนเข้าคลัง แล้วบันทึกยอดนำส่งด้วยมือลงในใบรับโอนสินค้า จากนั้นพนักงานแพ็คต้องตรวจนับจำนวนเทียบกับตัวเลขในใบอีกครั้ง ทำให้เสี่ยงนับผิดและใช้เวลานาน\", \"refStep\": \"ขั้นตอนที่ 6 (ใบรายงานการการผลิต/ส่งสินค้าเข้าคลัง FS-F1-021, WI การโอนสินค้าขึ้นคลัง)\", \"approver\": \"ผจก.คลังสินค้า\", \"hardware\": \"เครื่องสแกน Barcode/QR + ระบบ WMS เชื่อมกับ ERP สำหรับตัดยอด/รับเข้าคลังอัตโนมัติ\", \"language\": \"Thai\", \"priority\": \"high\", \"solution\": \"พนักงานบันทึกยอดนำส่งด้วยมือลงในใบรับโอนสินค้า และตรวจนับจำนวนเทียบกับตัวเลขในใบด้วยสายตา\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Prod, ขั้นตอน 6.1 ข้อ 7 ส่งมอบสินค้า Out going)\", \"resources\": \"ทีม IT/Automation 1-2 คน, ระยะเวลา 6-8 สัปดาห์, งบประมาณ ~150,000 บาท (เครื่องสแกน + ปรับปรุงระบบ WMS)\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 5, \"availability\": \"เวลาทำการ 8x5 (จันทร์-ศุกร์)\", \"redesignDesc\": \"ยอดรับสินค้าเข้าคลังที่บันทึกอัตโนมัติจากการสแกน Barcode พร้อมรายงานส่วนต่าง (ถ้ามี) แบบ Real-time\", \"recommendation\": \"เริ่มนำร่องกับสินค้ากลุ่มที่มีปริมาณนำส่งเข้าคลังสูงสุดก่อน\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_rd_1','AI Agent แจ้งเตือนและสรุปเอกสาร RFQ/Drawing อัตโนมัติ','R&D','{\"id\": \"uc_rd_1\", \"kpi\": \"ลดเวลาตั้งแต่ได้รับ RFQ ถึงเริ่มประเมินความสามารถผลิตลง 50%, ลดจำนวนรายการ RFQ ที่ประเมินต้นทุนเกินกำหนดนัด\", \"kqi\": \"(C) % รายการ RFQ ที่ใช้เวลาในการประเมินต้นทุนและราคาขายเกินกำหนดนัด\", \"qwp\": \"QWP-Axx การประเมินต้นทุนและราคาขาย Cost1\", \"roi\": \"คาดคืนทุนภายใน 6-8 เดือนจากเวลาที่ประหยัดได้ของวิศวกร RD และการปิดการขายที่เร็วขึ้น\", \"data\": 3, \"dept\": \"R&D\", \"name\": \"AI Agent แจ้งเตือนและสรุปเอกสาร RFQ/Drawing อัตโนมัติ\", \"risk\": 3, \"owner\": \"RD CENTER\", \"risks\": \"Drawing/3D Part อาจอยู่หลายรูปแบบไฟล์ (PDF, CAD) ต้องมีตัวแปลง/OCR รองรับ และต้องมีคนตรวจทานสรุปของ AI ก่อนใช้งานจริงในช่วงแรกเพื่อป้องกันตีความ Drawing ผิด\", \"score\": 75, \"users\": \"\", \"aiType\": \"agent\", \"impact\": 4, \"output\": \"การแจ้งเตือน RFQ ใหม่แบบเรียลไทม์ พร้อมสรุปสาระสำคัญของ RFQ/Drawing/3D Part ให้วิศวกรอ่านก่อนตัดสินใจ\", \"control\": \"รับเอกสาร RFQ และประเมินความสามารถในการผลิตจากประสบการณ์\", \"latency\": \"เร็ว (1-3 วินาที)\", \"problem\": \"เมื่อฝ่ายขายส่ง RFQ พร้อม Drawing/3D Part และใบทดกลยุทธ์มาให้ RD CENTER ปัจจุบันต้องแจ้งด้วยโทรศัพท์/LINE และวิศวกรต้องอ่านเอกสารทั้งหมดเองเพื่อสรุปสาระสำคัญก่อนประเมินความสามารถในการผลิต ทำให้ล่าช้าและอาจตกหล่นรายละเอียดสำคัญใน Drawing\", \"refStep\": \"ขั้นตอนรับ RFQ และประเมินความสามารถในการผลิต (SALE ส่ง RFQ+ใบทดกลยุทธ์ ให้ RD CENTER)\", \"approver\": \"ผจก. RD CENTER\", \"hardware\": \"AI Agent เชื่อมกับ WEB APPLICATION ภายในองค์กร + LLM สำหรับสรุปเอกสาร (RAG อ่าน RFQ/Drawing/3D Part)\", \"language\": \"Thai+Eng.\", \"priority\": \"high\", \"solution\": \"SALE ส่ง RFQ + ใบทดกลยุทธ์ให้ RD CENTER ทางอีเมล/ไฟล์ แล้วโทร/แชทแจ้งให้ทราบ จากนั้นวิศวกรอ่านเอกสารเองเพื่อประเมิณความสามารถในการผลิตจากประสบการณ์\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว RFQ intake)\", \"resources\": \"ทีม AI Dev 2 คน + ทีม IT, ระยะเวลา 8 สัปดาห์, งบประมาณ ~300,000 บาท\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 3, \"availability\": \"เวลาทำการ 8x5 (จันทร์-ศุกร์)\", \"redesignDesc\": \"การแจ้งเตือน RFQ ใหม่แบบเรียลไทม์ พร้อมสรุปสาระสำคัญของ RFQ/Drawing/3D Part ให้วิศวกรอ่านก่อนตัดสินใจ\", \"recommendation\": \"เริ่มจาก AI Agent แจ้งเตือนอัตโนมัติเมื่อมี RFQ ใหม่เข้า WEB APPLICATION ก่อนเป็น Quick Win แล้วต่อยอดด้วยฟีเจอร์สรุปเอกสาร RFQ/Drawing ด้วย AI\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_rd_2','AI จับคู่ความสามารถผลิต (Feasibility Matching) และค้นหา Out Source อัตโนมัติ','R&D','{\"id\": \"uc_rd_2\", \"kpi\": \"ลดเวลาการประเมิน Feasibility ต่อ RFQ ลง 40%, เพิ่มความแม่นยำของการตัดสินใจผลิตเอง/จ้างนอก\", \"kqi\": \"(A) % รายการใบเสนอราคาที่ปิดการขายแบบขายได้ ของสินค้าที่มีโอกาสเป็นสินค้ากลุ่ม A\", \"qwp\": \"QWP-Axx การประเมินต้นทุนและราคาขาย Cost1\", \"roi\": \"คาดคืนทุนภายใน 8-10 เดือนจากเวลาที่ประหยัดได้ของวิศวกรและ Purchase\", \"data\": 2, \"dept\": \"R&D\", \"name\": \"AI จับคู่ความสามารถผลิต (Feasibility Matching) และค้นหา Out Source อัตโนมัติ\", \"risk\": 3, \"owner\": \"RD CENTER\", \"risks\": \"ต้องมีเอกสาร FEASIBILITY และฐานข้อมูล Out Source ที่เป็นดิจิทัลและอัปเดตสม่ำเสมอ มิฉะนั้น AI จะจับคู่ผิดพลาด ต้องมีวิศวกรยืนยันผลก่อนสรุป\", \"score\": 70, \"users\": \"\", \"aiType\": \"recommend\", \"impact\": 4, \"output\": \"ผลประเมินความสามารถในการผลิต (ผลิตเอง/จ้างนอก) พร้อมรายชื่อ Out Source ที่เหมาะสม (ถ้าจำเป็น) ให้วิศวกรตรวจสอบ\", \"control\": \"ประเมินจากประสบการณ์ เทียบกับเอกสาร FEASIBILITY\", \"latency\": \"ปานกลาง (3-10 วินาที)\", \"problem\": \"การประเมินว่าโรงงานผลิตชิ้นงานใน RFQ ได้เองหรือไม่ ต้องอาศัยประสบการณ์วิศวกรเทียบกับเอกสาร FEASIBILITY ด้วยมือ และถ้าผลิตเองไม่ได้ต้องส่งเรื่องให้ Purchase ไปค้นหา Out Source เอง ทำให้ใช้เวลานานและผลลัพธ์ไม่สม่ำเสมอ\", \"refStep\": \"ขั้นตอนประเมินความสามารถในการผลิต (ผลิตได้เอง / ผลิตไม่ได้เอง -> ส่ง Purchase หา Out Source)\", \"approver\": \"ผจก. RD CENTER\", \"hardware\": \"ระบบ AI Matching เทียบข้อมูล RFQ กับฐานข้อมูลเอกสาร FEASIBILITY + ฐานข้อมูล Out Source Supplier\", \"language\": \"Thai\", \"priority\": \"med\", \"solution\": \"วิศวกรประเมินความสามารถในการผลิตจากประสบการณ์ส่วนตัว เทียบกับเอกสาร FEASIBILITY ด้วยมือ หากผลิตไม่ได้เองจะส่งข้อมูลให้ Purchase ไปหา Out Source เอง\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว FEASIBILITY / Out Source)\", \"resources\": \"ทีม AI Dev 2 คน + ทีม Purchase, ระยะเวลา 10 สัปดาห์, งบประมาณ ~350,000 บาท\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 3, \"availability\": \"เวลาทำการ 8x5 (จันทร์-ศุกร์)\", \"redesignDesc\": \"ผลประเมินความสามารถในการผลิต (ผลิตเอง/จ้างนอก) พร้อมรายชื่อ Out Source ที่เหมาะสม (ถ้าจำเป็น) ให้วิศวกรตรวจสอบ\", \"recommendation\": \"เริ่มนำร่องกับกลุ่มสินค้าที่มีเอกสาร FEASIBILITY ครบถ้วนอยู่แล้วก่อน แล้วขยายฐานข้อมูลให้ครอบคลุมมากขึ้น\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_rd_3','AI เสนอทางเลือกกระบวนการผลิต ประเมินต้นทุน และแนะนำ Formulation (Cost1/Cost2)','R&D','{\"id\": \"uc_rd_3\", \"kpi\": \"ลด (B) % Item ที่ Cost2 สูงกว่า Cost1 เกินเกณฑ์ (ประเมินต้นทุนผิด), ลดเวลาจัดทำ Cost1 ต่อรายการ\", \"kqi\": \"(B) % Item Total Production Cost ของ Cost 2 > Cost 1 (Cost 1 ประเมินต้นทุนผิด)\", \"qwp\": \"QWP-Axx การประเมินต้นทุนและราคาขาย Cost1\", \"roi\": \"คาดคืนทุนภายใน 12-18 เดือนจากการลดความคลาดเคลื่อนของต้นทุนและเวลาออกแบบที่ลดลง\", \"data\": 2, \"dept\": \"R&D\", \"name\": \"AI เสนอทางเลือกกระบวนการผลิต ประเมินต้นทุน และแนะนำ Formulation (Cost1/Cost2)\", \"risk\": 5, \"owner\": \"RD CENTER (PE)\", \"risks\": \"ต้องมีข้อมูลย้อนหลังของ Process Design, Formulation และ Cost1/Cost2 จำนวนมากพอให้ AI เรียนรู้ และต้องมีวิศวกรตรวจทานทางเลือกที่ AI เสนอก่อนใช้จริงเสมอ เพราะผลกระทบต่อคุณภาพ/ต้นทุนสูง\", \"users\": \"\", \"aiType\": \"generative\", \"impact\": 5, \"latency\": \"แบบกลุ่ม/ไม่เร่งด่วน (Batch)\", \"refStep\": \"ขั้นตอนออกแบบกระบวนการผลิตและจัดทำ Cost1 (คัดเลือก Formulation, คำนวณ Cyctime, จัดทำ Cost1)\", \"approver\": \"ผจก. RD CENTER\", \"hardware\": \"โมเดล Generative/Optimization AI ต่อกับฐานข้อมูล Formulation, Process Design Sheet และประวัติ Cost1/Cost2 ในอดีต\", \"language\": \"Thai\", \"solution\": \"วิศวกรออกแบบกระบวนการผลิตและคัดเลือก Formulation จากประสบการณ์ จัดทำ Cost1 ด้วย Excel แบบ Manual แล้วส่งให้ Sale ทำใบเสนอราคา\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว Process Design / Cost1 / Formulation)\", \"resources\": \"ทีม AI Dev 3 คน + ทีม PE, ระยะเวลา 20 สัปดาห์, งบประมาณ ~1,000,000 บาท\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 2, \"availability\": \"เวลาทำการ 8x5 (จันทร์-ศุกร์)\", \"redesignDesc\": \"ทางเลือกกระบวนการผลิตหลายรูปแบบ (A,B,C,D) พร้อมประเมินต้นทุนแต่ละแบบ และคำแนะนำ Formulation No. พร้อมเหตุผลประกอบ\", \"dataAvailable\": \"Product Quality Check Sheet\\nFile Process Design Sheet\\nCost 2 และใบสั่งผลิตแม่พิมพ์และ Tooling\", \"recommendation\": \"เริ่มจากการให้ AI เสนอ Formulation No. พร้อมเหตุผล (ขอบเขตแคบกว่า ข้อมูลพร้อมกว่า) ก่อนเป็น Quick Win แล้วค่อยขยายไปสู่การเสนอทางเลือกกระบวนการผลิตทั้งหมด + ประเมินต้นทุนอัตโนมัติ\", \"dataSensitivity\": \"ลับ (Confidential)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_rd_4','AI ตรวจสอบความปลอดภัยผลิตภัณฑ์และจับคู่ QFD กับ Check Sheet (QA)','R&D','{\"id\": \"uc_rd_4\", \"kpi\": \"ลด (A) %Reject สินค้าตัวอย่างสะสม, ลดเวลาตรวจสอบ Safety Part/QFD2 ต่อรายการ\", \"kqi\": \"(A) %Reject สินค้าตัวอย่างสะสม\", \"qwp\": \"QWP การวางแผนและผลิตสินค้าใหม่ (Advance New Product and Quality Planning)\", \"roi\": \"คาดคืนทุนภายใน 10-12 เดือนจากการลดของเสียจากตัวอย่างและเวลาตรวจสอบของ QA\", \"data\": 2, \"dept\": \"R&D\", \"name\": \"AI ตรวจสอบความปลอดภัยผลิตภัณฑ์และจับคู่ QFD กับ Check Sheet (QA)\", \"risk\": 5, \"owner\": \"QA\", \"risks\": \"ต้องแปลง Check List/WI ให้อยู่ในรูปแบบดิจิทัลที่ AI อ่านได้ทั้งหมดก่อน และควรให้ QA ยืนยันผลการจับคู่ของ AI ทุกครั้งในช่วงแรกเพื่อความปลอดภัยของผลิตภัณฑ์\", \"score\": 70, \"users\": \"\", \"aiType\": \"rag\", \"impact\": 4, \"output\": \"ผลตรวจสอบ Safety Part และการจับคู่ QFD2 กับ Check Sheet อัตโนมัติ พร้อมระบุจุด SC Point ที่ต้องเฝ้าระวัง\", \"control\": \"ตรวจสอบด้วย Manual ตาม WI โดยใช้ Check List ต่างๆ\", \"latency\": \"ปานกลาง (3-10 วินาที)\", \"problem\": \"หลังรับ Sample Request (SR) ฝ่าย QA ต้องวิเคราะห์ความปลอดภัยผลิตภัณฑ์ (Safety Part), กำหนดจุด SC Point และพิจารณา QFD2 ด้านการประกันคุณภาพ โดยตรวจสอบด้วยมือตาม WI และ Check List หลายชุด ทำให้ใช้เวลานานและอาจตรวจข้ามหัวข้อสำคัญ\", \"refStep\": \"ขั้นตอน QA รับ SR: วิเคราะห์ Safety Part, กำหนด SC Point, พิจารณา QFD2 ด้านการประกันคุณภาพ\", \"approver\": \"ผจก. RD CENTER\", \"hardware\": \"ระบบ RAG (ค้นหา/จับคู่เอกสาร) เชื่อมฐานข้อมูล Check Sheet, WI และข้อกำหนดความปลอดภัยผลิตภัณฑ์\", \"language\": \"Thai\", \"priority\": \"med\", \"solution\": \"QA รับ SR แล้วตรวจสอบด้วยมือตาม WI โดยอ้างอิง Check List ต่างๆ เพื่อวิเคราะห์ Safety Part และ SC Point\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว QA Safety/QFD2)\", \"resources\": \"ทีม AI Dev 2 คน + ทีม QA, ระยะเวลา 10 สัปดาห์, งบประมาณ ~350,000 บาท\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 3, \"availability\": \"เวลาทำการ 8x5 (จันทร์-ศุกร์)\", \"redesignDesc\": \"ผลตรวจสอบ Safety Part และการจับคู่ QFD2 กับ Check Sheet อัตโนมัติ พร้อมระบุจุด SC Point ที่ต้องเฝ้าระวัง\", \"recommendation\": \"นำร่องกับกลุ่มผลิตภัณฑ์ที่มี Check List ครบถ้วนเป็นดิจิทัลอยู่แล้วก่อน\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_rd_5','AI Agent ติดตามสถานะแผน NPD Master Plan อัตโนมัติ','R&D','{\"id\": \"uc_rd_5\", \"kpi\": \"ลด (C) %ในการทำตัวอย่างไม่ทันกำหนด, เพิ่ม % โครงการ NPD ที่ส่งมอบตรงตามแผน\", \"kqi\": \"(C) %ในการทำตัวอย่างไม่ทันกำหนด\", \"qwp\": \"QWP การวางแผนและผลิตสินค้าใหม่ (Advance New Product and Quality Planning)\", \"roi\": \"คาดคืนทุนภายใน 6 เดือนจากการลดความล่าช้าของโครงการ NPD\", \"data\": 3, \"dept\": \"R&D\", \"name\": \"AI Agent ติดตามสถานะแผน NPD Master Plan อัตโนมัติ\", \"risk\": 2, \"owner\": \"RD CENTER\", \"risks\": \"ต้องมีการอัปเดตสถานะงานในระบบสม่ำเสมอโดยผู้รับผิดชอบแต่ละขั้นตอน มิฉะนั้น AI Agent จะแจ้งเตือนผิดพลาด\", \"score\": 83, \"users\": \"\", \"aiType\": \"agent\", \"impact\": 3, \"output\": \"การแจ้งเตือนสถานะและความคืบหน้าของแผน NPD Master Plan แบบอัตโนมัติให้ผู้เกี่ยวข้องทุกฝ่าย\", \"control\": \"ติดตามสถานะด้วย Manual\", \"latency\": \"แบบกลุ่ม/ไม่เร่งด่วน (Batch)\", \"problem\": \"การติดตามสถานะแผนพัฒนาผลิตภัณฑ์ใหม่ (NPD Master Plan / Project Master Plan) ปัจจุบันทำด้วยมือ (Manual) ทำให้ทราบความล่าช้าของแต่ละขั้นตอนช้า และไม่มีการแจ้งเตือนผู้เกี่ยวข้องเมื่อมีงานใกล้เกินกำหนด\", \"refStep\": \"ขั้นตอนจัดทำแผน NPD MASTER PLAN และติดตามสถานะ\", \"approver\": \"ผจก. RD CENTER\", \"hardware\": \"AI Agent เชื่อมกับไฟล์/ระบบ Project Master Plan เพื่อติดตามสถานะและแจ้งเตือนอัตโนมัติ\", \"language\": \"Thai\", \"priority\": \"high\", \"solution\": \"ผู้รับผิดชอบโครงการติดตามสถานะแผน NPD Master Plan ด้วยมือ (Manual) ผ่านไฟล์ Project Master Plan\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว NPD Master Plan)\", \"resources\": \"ทีม AI Dev 1-2 คน, ระยะเวลา 6 สัปดาห์, งบประมาณ ~200,000 บาท\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 4, \"availability\": \"เวลาทำการ 8x5 (จันทร์-ศุกร์)\", \"redesignDesc\": \"การแจ้งเตือนสถานะและความคืบหน้าของแผน NPD Master Plan แบบอัตโนมัติให้ผู้เกี่ยวข้องทุกฝ่าย\", \"recommendation\": \"เริ่มนำร่องกับโครงการ NPD ที่มีความสำคัญสูงหรือมีความเสี่ยงล่าช้าก่อน\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10'),('uc_rd_6','AI ช่วยคำนวณพารามิเตอร์การทดลองผลิตสินค้าตัวอย่าง (Trial Production Parameter Assistant)','R&D','{\"id\": \"uc_rd_6\", \"kpi\": \"ลดจำนวนรอบ Trial & Error ต่อผลิตภัณฑ์ใหม่ลง 30-50%, ลด (C) %ในการทำตัวอย่างไม่ทันกำหนด\", \"kqi\": \"(C) %ในการทำตัวอย่างไม่ทันกำหนด, (A) %Reject สินค้าตัวอย่างสะสม\", \"qwp\": \"QWP การวางแผนและผลิตสินค้าใหม่ (Advance New Product and Quality Planning)\", \"roi\": \"คาดคืนทุนภายใน 10-12 เดือนจากเวลาและวัตถุดิบที่ประหยัดได้จากการลดรอบ Trial & Error\", \"data\": 2, \"dept\": \"R&D\", \"name\": \"AI ช่วยคำนวณพารามิเตอร์การทดลองผลิตสินค้าตัวอย่าง (Trial Production Parameter Assistant)\", \"risk\": 3, \"owner\": \"RD CENTER (PE)\", \"risks\": \"ต้องมีข้อมูลผลการทดลองย้อนหลัง (P-CAR FORM 3) ที่บันทึกอย่างเป็นระบบเพียงพอสำหรับเทรนโมเดล และต้องมีวิศวกรตรวจสอบ/ปรับแต่งค่าที่ AI แนะนำก่อนใช้ทดลองจริงเสมอ\", \"score\": 70, \"users\": \"\", \"aiType\": \"numeric\", \"impact\": 4, \"output\": \"ค่าพารามิเตอร์เริ่มต้นที่แนะนำ (Curing Time, Molding Weight, Machine Setting ฯลฯ) สำหรับการทดลองผลิตสินค้าตัวอย่างแต่ละรุ่น\", \"control\": \"เตรียม PARAMETER สำหรับทดลองด้วยชุดเครื่องมือที่มีอยู่ (Manual)\", \"latency\": \"ปานกลาง (3-10 วินาที)\", \"problem\": \"ขั้นตอนทดลอง/ผลิตสินค้าตัวอย่าง ต้องเตรียมพารามิเตอร์ (TS2/T90, Curing Time, Molding Weight, Machine Setting, ขนาด Runner และ Injection Condition) ด้วยการคำนวณ Manual จากประสบการณ์ และมักต้องผ่านกระบวนการ Trial & Error หลายรอบก่อนได้ค่าที่เหมาะสม\", \"refStep\": \"ขั้นตอนทดลอง/ผลิตสินค้าตัวอย่าง (เตรียม PARAMETER, TRIAL, บันทึกผลใน P-CAR FORM 3)\", \"approver\": \"ผจก. RD CENTER\", \"hardware\": \"โมเดล Predictive ML (เช่น Regression/Gradient Boosting) เทรนจากประวัติผลทดลอง P-CAR FORM 3 ในอดีต เพื่อทำนายค่าพารามิเตอร์เริ่มต้นที่ใกล้เคียงค่าที่เหมาะสมที่สุด\", \"language\": \"Thai\", \"priority\": \"med\", \"solution\": \"วิศวกรเตรียมพารามิเตอร์ด้วยชุดเครื่องมือที่มีอยู่แบบ Manual แล้วทดลองจริง หากไม่ผ่านต้องแก้ไขปัญหาตามเครื่องมือที่มีและประสบการณ์ (Trial & Error) พร้อมบันทึกผลใน P-CAR FORM 3\", \"attachRef\": \"ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว Trial Production)\", \"resources\": \"ทีม AI Dev 2 คน + ทีม PE, ระยะเวลา 12 สัปดาห์, งบประมาณ ~450,000 บาท\", \"attachment\": null, \"preparedBy\": \"ทีม AI Transformation\", \"feasibility\": 3, \"availability\": \"เวลาทำการ 8x5 (จันทร์-ศุกร์)\", \"redesignDesc\": \"ค่าพารามิเตอร์เริ่มต้นที่แนะนำ (Curing Time, Molding Weight, Machine Setting ฯลฯ) สำหรับการทดลองผลิตสินค้าตัวอย่างแต่ละรุ่น\", \"recommendation\": \"เริ่มเก็บข้อมูล P-CAR FORM 3 ให้เป็นดิจิทัลและเป็นระบบก่อน แล้วนำร่องโมเดลทำนายกับกลุ่มผลิตภัณฑ์ที่มีข้อมูลย้อนหลังมากที่สุด\", \"dataSensitivity\": \"ภายในองค์กร (Internal)\"}','2026-09-09 07:28:36','2026-09-10 01:58:10');
